package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import okhttp3.*;import org.json.*;import java.util.*;import java.util.concurrent.TimeUnit;
/** Only starts for a visible Markets panel. No provider credentials bundled. */
final class MarketStream extends PanelUi {
 final Handler main=new Handler(Looper.getMainLooper());final OkHttpClient http=new OkHttpClient.Builder().pingInterval(20,TimeUnit.SECONDS).readTimeout(0,TimeUnit.SECONDS).build(); final SharedPreferences prefs;
 WebSocket ws;int generation;boolean running;int attempts;String kind;TextView status;final Map<String,TextView> values=new LinkedHashMap<>();final Map<String,Long> times=new HashMap<>();final Map<String,Double> prices=new HashMap<>();final Map<String,String> detail=new HashMap<>();Runnable retry,heartbeat,stale;
 static final String[] CRYPTO={"BTCUSDT","ETHUSDT","SOLUSDT","BNBUSDT","XRPUSDT","ADAUSDT","DOGEUSDT"},FX={"EUR/USD","GBP/USD","USD/JPY","USD/THB","USD/CHF","AUD/USD"},METAL={"XAU/USD","XAG/USD","XPT/USD","XPD/USD"};
 MarketStream(Activity a){super(a);prefs=a.getSharedPreferences("live_markets53",0);}
 void stop(){if(running){SharedPreferences.Editor save=prefs.edit();for(String symbol:prices.keySet()){try{save.putString("q:"+symbol,new JSONObject().put("p",prices.get(symbol)).put("t",times.get(symbol)).toString());}catch(Exception ignored){}}save.apply();}running=false;generation++;if(retry!=null)main.removeCallbacks(retry);if(heartbeat!=null)main.removeCallbacks(heartbeat);if(stale!=null)main.removeCallbacks(stale);if(ws!=null){ws.cancel();ws=null;}}
 void attach(LinearLayout l,String mode,TextView external){stop();kind=mode;running=true;attempts=0;values.clear();times.clear();prices.clear();detail.clear();status=external;String[] symbols=kind.equals("Crypto")?CRYPTO:kind.equals("Forex")?FX:METAL;for(String s:symbols){TextView v=text(s+"   —",19,WHITE,true);v.setBackground(bg(CARD));l.addView(v,new LinearLayout.LayoutParams(-1,dp(66)));values.put(s,v);try{JSONObject j=new JSONObject(prefs.getString("q:"+s,""));long stamp=j.getLong("t");double p=j.getDouble("p");if(stamp>0&&Double.isFinite(p)&&p>0){times.put(s,stamp);prices.put(s,p);detail.put(s,"Cached");paint(s);}}catch(Exception ignored){}}l.addView(text(kind.equals("Crypto")?"Binance public spot · USDT is not USD":"Twelve Data · provider quote frequency / entitlement applies",12,MUTE,false));if(!kind.equals("Crypto")){action(l,"Set personal market feed key",()->{EditText key=new EditText(a);key.setSingleLine();key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(a).setTitle("Twelve Data personal API key").setMessage("Session only; no key saved or bundled. Provider plan must allow these symbols. For distributed use configure an authorized backend.").setView(key).setPositiveButton("Connect",(d,w)->{personalKey=key.getText().toString().trim();reconnect();}).setNegativeButton("Cancel",null).show();});}connect();stale=new Runnable(){public void run(){if(!running)return;for(String s:values.keySet())paint(s);main.postDelayed(this,5000);}};main.postDelayed(stale,5000);}
 String personalKey="";void reconnect(){if(!running)return;generation++;if(ws!=null)ws.cancel();if(retry!=null)main.removeCallbacks(retry);if(heartbeat!=null)main.removeCallbacks(heartbeat);for(String s:values.keySet())if(prices.containsKey(s)){detail.put(s,"Cached");paint(s);}attempts=0;connect();}
 void connect(){if(!running)return;boolean crypto=kind.equals("Crypto");if(!crypto&&personalKey.isEmpty()){status.setText("Streaming requires your authorized Twelve Data key · cached only");return;}final int gen=++generation;String url;if(crypto){StringJoiner j=new StringJoiner("/");for(String s:CRYPTO)j.add(s.toLowerCase(Locale.ROOT)+"@ticker");url="wss://stream.binance.com:443/stream?streams="+j;}else{url="wss://ws.twelvedata.com/v1/quotes/price?apikey="+android.net.Uri.encode(personalKey);}status.setText("Connecting…");ws=http.newWebSocket(new Request.Builder().url(url).build(),new WebSocketListener(){@Override public void onOpen(WebSocket socket,Response r){main.post(()->{if(!running||gen!=generation)return;status.setText("Connected · awaiting verified quotes");if(!crypto){try{JSONObject j=new JSONObject();j.put("action","subscribe");j.put("params",new JSONObject().put("symbols",String.join(",",values.keySet())));socket.send(j.toString());}catch(Exception ignored){}heartbeat=new Runnable(){public void run(){if(!running||gen!=generation)return;socket.send("{\"action\":\"heartbeat\"}");main.postDelayed(this,10000);}};main.postDelayed(heartbeat,10000);}});}@Override public void onMessage(WebSocket socket,String raw){try{JSONObject j=new JSONObject(raw);if(crypto){JSONObject q=j.getJSONObject("data");String s=q.getString("s");double p=q.getDouble("c");long t=q.getLong("E");String ch=q.optString("P","");main.post(()->quote(gen,s,p,t,ch.isEmpty()?"":"24h "+ch+"%"));}else{String event=j.optString("event");if(event.equals("price")){String s=j.getString("symbol");double p=j.getDouble("price");long t=j.getLong("timestamp");if(t<100000000000L)t*=1000;final long time=t;main.post(()->quote(gen,s,p,time,""));}else if(event.equals("subscribe-status")){String stat=j.optString("status");main.post(()->{if(running&&gen==generation)status.setText("Subscription: "+stat+" · awaiting quotes / check plan");});}}}catch(Exception ignored){}}@Override public void onFailure(WebSocket s,Throwable t,Response r){main.post(()->closed(gen));}@Override public void onClosed(WebSocket s,int c,String r){main.post(()->closed(gen));}});}
 void closed(int gen){if(!running||gen!=generation)return;status.setText("Disconnected · cached quotes · retrying");for(String s:values.keySet())if(prices.containsKey(s)){detail.put(s,"Cached");paint(s);}if(heartbeat!=null)main.removeCallbacks(heartbeat);retry=()->{if(running&&gen==generation)connect();};main.postDelayed(retry,Math.min(60000,2000L*(1L<<Math.min(5,attempts++))));}
 void quote(int gen,String s,double p,long t,String change){if(!running||gen!=generation||!values.containsKey(s)||!Double.isFinite(p)||p<=0||t<=0||t>System.currentTimeMillis()+300000||t<times.getOrDefault(s,0L))return;attempts=0;Double previous=prices.get(s);prices.put(s,p);times.put(s,t);detail.put(s,"Stream "+change);paint(s);if(previous!=null&&Double.compare(p,previous)!=0){TextView v=values.get(s);v.setTextColor(p>previous?0xff22c55e:0xffef4444);main.postDelayed(()->{if(running&&gen==generation&&values.get(s)==v)v.setTextColor(WHITE);},700);}status.setText("Receiving provider quotes · see each timestamp");try{JSONObject j=new JSONObject().put("p",p).put("t",t); // throttle disk writes per symbol
 long last=prefs.getLong("saved:"+s,0);if(System.currentTimeMillis()-last>10000){prefs.edit().putString("q:"+s,j.toString()).putLong("saved:"+s,System.currentTimeMillis()).apply();}}catch(Exception ignored){}}
 void paint(String s){if(!prices.containsKey(s))return;long t=times.get(s);String state=detail.get(s);if(state.startsWith("Stream")&&System.currentTimeMillis()-t>(kind.equals("Crypto")?15000:120000))state="Stale / no recent tick";String date=new java.text.SimpleDateFormat("dd/MM HH:mm:ss",Locale.US).format(new Date(t));values.get(s).setText(s+"   "+String.format(Locale.US,"%,.8f",prices.get(s)).replaceAll("0+$","").replaceAll("\\.$","")+"\n"+state+" · "+date);}
}
